using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Animations;
using UnityEngine.Playables;
using UnityEditor;
using UnityEditor.Animations;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using Praktikum5.FSM;
using UTS.Characters;

[InitializeOnLoad]
public static class CrouchPosePolish
{
    static string Folder=>Path.Combine(Directory.GetParent(Application.dataPath).FullName,"Library/ZU_CrouchPolish");
    static string last=SessionState.GetString("ZU.CrouchPolish.Command","");
    [Serializable] class Cmd{public string op,nonce;}
    static CrouchPosePolish(){EditorApplication.update+=Tick;}
    static void Tick(){var f=Path.Combine(Folder,"command.json");if(!File.Exists(f)||EditorApplication.isCompiling||EditorApplication.isUpdating)return;var t=File.ReadAllText(f);if(t==last)return;last=t;SessionState.SetString("ZU.CrouchPolish.Command",t);try{var c=JsonUtility.FromJson<Cmd>(t);if(c.op=="probe")Probe();else if(c.op=="build")Build();else if(c.op=="apply")Apply();else if(c.op=="feet")RefineFeet();else if(c.op=="walk")BuildWalk();else if(c.op=="apply-walk")ApplyWalk();else if(c.op=="refresh")AssetDatabase.Refresh();}catch(Exception e){File.WriteAllText(Path.Combine(Folder,"error.txt"),e.ToString());Debug.LogException(e);}}
    static AnimationClip Clip(string name)=>AssetDatabase.LoadAllAssetsAtPath("Assets/CharacterUpgrade/Animations/Player/"+name+".fbx").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__preview"));
    static void Probe(){var p=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var a=p.GetComponent<HumanoidAnimationDriver>().Animator;var lines=new List<string>{"Scene="+SceneManager.GetActiveScene().path+" playing="+Application.isPlaying,"Player enabled="+p.enabled+" active="+p.gameObject.activeInHierarchy+" controller="+p.GetComponent<CharacterController>().enabled+" animator="+a.enabled,"PlayerVisual="+a.transform.localPosition+" "+a.transform.localRotation+" "+a.transform.localScale};foreach(var name in new[]{"Crouching Idle","Crouched Walking"}){var clip=Clip(name);lines.Add(name+" human="+clip.humanMotion+" duration="+clip.length);foreach(var b in AnimationUtility.GetCurveBindings(clip)){var curve=AnimationUtility.GetEditorCurve(clip,b);lines.Add(b.type.Name+" "+b.path+" "+b.propertyName+" sample="+curve.Evaluate(clip.length*.5f));}}File.WriteAllLines(Path.Combine(Folder,"probe.txt"),lines);}
    static string NewClip=>"Assets/CharacterUpgrade/Animations/Player/Crouch Idle Balanced.anim";
    static void Build(){
        if(Application.isPlaying)throw new Exception("Build in Edit mode");if(AssetDatabase.LoadAssetAtPath<AnimationClip>(NewClip))throw new Exception("Balanced clip exists; inspect before modifying it");var source=Clip("Crouched Walking");var bindings=AnimationUtility.GetCurveBindings(source);var values=new Dictionary<string,float>();foreach(var b in bindings){var c=AnimationUtility.GetEditorCurve(source,b);float sum=0;for(int i=0;i<64;i++)sum+=c.Evaluate(source.length*i/64f);values[b.propertyName]=sum/64;}
        foreach(var key in values.Keys.ToArray())if(key.StartsWith("Left ")){var right="Right "+key.Substring(5);if(values.ContainsKey(right)){float mean=(values[key]+values[right])*.5f;values[key]=values[right]=mean;}}
        foreach(var key in values.Keys.ToArray())if((key.Contains("Spine")||key.Contains("Chest")||key.StartsWith("Head ")||key.StartsWith("Neck "))&&(key.Contains("Left-Right")))values[key]=0;
        var body=new Quaternion(values["RootQ.x"],values["RootQ.y"],values["RootQ.z"],values["RootQ.w"]).normalized;var bodyAngles=body.eulerAngles;body=Quaternion.Euler(Mathf.DeltaAngle(0,bodyAngles.x),bodyAngles.y,0);values["RootQ.x"]=body.x;values["RootQ.y"]=body.y;values["RootQ.z"]=body.z;values["RootQ.w"]=body.w;
        values["RootT.x"]=0;values["RootT.z"]=0;values["RootT.y"]-=.04f;
        foreach(var channel in new[]{"y","z"}){float mid=(values["LeftFootT."+channel]+values["RightFootT."+channel])*.5f;values["LeftFootT."+channel]=values["RightFootT."+channel]=mid;}
        float width=(Mathf.Abs(values["LeftFootT.x"])+Mathf.Abs(values["RightFootT.x"]))*.5f;values["LeftFootT.x"]=-width;values["RightFootT.x"]=width;
        var foot=new Quaternion(values["LeftFootQ.x"],values["LeftFootQ.y"],values["LeftFootQ.z"],values["LeftFootQ.w"]).normalized;var rightFoot=new Quaternion(values["RightFootQ.x"],values["RightFootQ.y"],values["RightFootQ.z"],values["RightFootQ.w"]).normalized;foot=Quaternion.Slerp(foot,rightFoot,.5f);foreach(var side in new[]{"Left","Right"}){values[side+"FootQ.x"]=foot.x;values[side+"FootQ.y"]=foot.y;values[side+"FootQ.z"]=foot.z;values[side+"FootQ.w"]=foot.w;}
        var clip=new AnimationClip{name="Crouch Idle Balanced",frameRate=30};var curves=new List<AnimationCurve>();foreach(var b in bindings){float v=values[b.propertyName];if(b.propertyName=="Spine Front-Back"||b.propertyName=="Chest Front-Back")curves.Add(new AnimationCurve(new Keyframe(0,v,0,0),new Keyframe(1.5f,v+.006f,0,0),new Keyframe(3,v,0,0)));else curves.Add(AnimationCurve.Constant(0,3,v));}AnimationUtility.SetEditorCurves(clip,bindings,curves.ToArray());var settings=AnimationUtility.GetAnimationClipSettings(source);settings.startTime=0;settings.stopTime=3;settings.loopTime=true;settings.loopBlend=true;settings.loopBlendPositionXZ=true;AnimationUtility.SetAnimationClipSettings(clip,settings);clip.EnsureQuaternionContinuity();AssetDatabase.CreateAsset(clip,NewClip);AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(Folder,"built.txt"),"Humanoid="+clip.humanMotion+" duration="+clip.length+" curves="+bindings.Length);Preview(clip);
    }
    static void Preview(AnimationClip clip){
        var live=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>().GetComponent<HumanoidAnimationDriver>().Animator;var scene=EditorSceneManager.NewPreviewScene();var go=UnityEngine.Object.Instantiate(live.gameObject);SceneManager.MoveGameObjectToScene(go,scene);go.transform.SetPositionAndRotation(Vector3.up*(1+live.transform.localPosition.y),Quaternion.identity);foreach(var c in go.GetComponentsInChildren<MonoBehaviour>())c.enabled=false;var a=go.GetComponent<Animator>();a.runtimeAnimatorController=null;a.cullingMode=AnimatorCullingMode.AlwaysAnimate;a.applyRootMotion=false;a.Rebind();var graph=PlayableGraph.Create("Balanced crouch preview");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var motion=AnimationClipPlayable.Create(graph,clip);motion.SetApplyFootIK(true);var output=AnimationPlayableOutput.Create(graph,"Pose",a);output.SetSourcePlayable(motion);graph.Play();motion.SetTime(1);graph.Evaluate(0);
        var meshes=new List<Mesh>();foreach(var r in go.GetComponentsInChildren<SkinnedMeshRenderer>()){var mesh=new Mesh();r.BakeMesh(mesh);meshes.Add(mesh);var child=new GameObject("Baked pose");child.transform.SetParent(r.transform,false);child.AddComponent<MeshFilter>().sharedMesh=mesh;child.AddComponent<MeshRenderer>().sharedMaterials=r.sharedMaterials;r.enabled=false;}
        var cg=new GameObject("Preview camera");SceneManager.MoveGameObjectToScene(cg,scene);var cam=cg.AddComponent<Camera>();cam.scene=scene;cam.orthographic=true;cam.orthographicSize=1.02f;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.25f,.28f,.32f);var lg=new GameObject("Preview light");SceneManager.MoveGameObjectToScene(lg,scene);var light=lg.AddComponent<Light>();light.type=LightType.Directional;light.intensity=2;lg.transform.rotation=Quaternion.Euler(35,-35,0);var sheet=new Texture2D(1200,600,TextureFormat.RGB24,false);
        try{for(int i=0;i<3;i++){var dir=i==0?Vector3.forward:i==1?Vector3.right:-Vector3.forward;cam.transform.position=dir*4+Vector3.up*.9f;cam.transform.LookAt(Vector3.up*.85f);var rt=new RenderTexture(400,600,24);cam.targetTexture=rt;cam.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(400,600,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,400,600),0,0);tex.Apply();sheet.SetPixels(i*400,0,400,600,tex.GetPixels());RenderTexture.active=prev;cam.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);}sheet.Apply();File.WriteAllBytes(Path.Combine(Folder,"balanced-preview.png"),sheet.EncodeToPNG());}finally{UnityEngine.Object.DestroyImmediate(sheet);graph.Destroy();foreach(var m in meshes)UnityEngine.Object.DestroyImmediate(m);EditorSceneManager.ClosePreviewScene(scene);}
    }
    static Quaternion Q(AnimationClip clip,string prefix){return new Quaternion(C(clip,prefix+".x"),C(clip,prefix+".y"),C(clip,prefix+".z"),C(clip,prefix+".w")).normalized;}
    static float C(AnimationClip clip,string property)=>AnimationUtility.GetEditorCurve(clip,EditorCurveBinding.FloatCurve("",typeof(Animator),property)).Evaluate(clip.length*.5f);
    static void RefineFeet(){var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(NewClip);var idle=Clip("Idle");var sourceBody=Q(idle,"RootQ");var body=Q(clip,"RootQ");var sourceYaw=Quaternion.Euler(0,sourceBody.eulerAngles.y,0);var bodyYaw=Quaternion.Euler(0,body.eulerAngles.y,0);var flat=Quaternion.Slerp(Quaternion.Inverse(sourceYaw)*sourceBody*Q(idle,"LeftFootQ"),Quaternion.Inverse(sourceYaw)*sourceBody*Q(idle,"RightFootQ"),.5f);foreach(var side in new[]{"Left","Right"}){var q=Quaternion.Inverse(body)*bodyYaw*Quaternion.Euler(0,side=="Left"?-4:4,0)*flat;float[] v={q.x,q.y,q.z,q.w};string[] ch={"x","y","z","w"};for(int i=0;i<4;i++)AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve("",typeof(Animator),side+"FootQ."+ch[i]),AnimationCurve.Constant(0,3,v[i]));}AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve("",typeof(Animator),"Neck Nod Down-Up"),AnimationCurve.Constant(0,3,.3f));AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve("",typeof(Animator),"Head Nod Down-Up"),AnimationCurve.Constant(0,3,.1f));clip.EnsureQuaternionContinuity();EditorUtility.SetDirty(clip);AssetDatabase.SaveAssets();Preview(clip);}
    static string NewWalk=>"Assets/CharacterUpgrade/Animations/Player/Crouch Walk Balanced.anim";
    static void BuildWalk(){
        if(Application.isPlaying)throw new Exception("Build in Edit mode");if(AssetDatabase.LoadAssetAtPath<AnimationClip>(NewWalk))throw new Exception("Balanced walk exists; inspect first");var source=Clip("Crouched Walking");var bindings=AnimationUtility.GetCurveBindings(source);var sourceCurves=bindings.ToDictionary(b=>b.propertyName,b=>AnimationUtility.GetEditorCurve(source,b));var means=new Dictionary<string,float>();foreach(var kv in sourceCurves){float sum=0;for(int i=0;i<64;i++)sum+=kv.Value.Evaluate(source.length*i/64);means[kv.Key]=sum/64;}
        Func<string,float,float> val=(key,t)=>sourceCurves[key].Evaluate(t);Func<string,float,Quaternion> rot=(key,t)=>new Quaternion(val(key+".x",t),val(key+".y",t),val(key+".z",t),val(key+".w",t)).normalized;float roll=0;for(int i=0;i<64;i++)roll+=Mathf.DeltaAngle(0,rot("RootQ",source.length*i/64f).eulerAngles.z)/64;
        var keys=bindings.ToDictionary(b=>b.propertyName,b=>new List<Keyframe>());for(int frame=0;frame<=64;frame++){float time=source.length*frame/64;var values=sourceCurves.ToDictionary(k=>k.Key,k=>k.Value.Evaluate(time));var original=rot("RootQ",time);var e=original.eulerAngles;var leveled=Quaternion.Euler(e.x,e.y,Mathf.DeltaAngle(0,e.z)-roll);float[] q={leveled.x,leveled.y,leveled.z,leveled.w};string[] channels={"x","y","z","w"};for(int i=0;i<4;i++)values["RootQ."+channels[i]]=q[i];
            foreach(var side in new[]{"LeftFoot","RightFoot","LeftHand","RightHand"}){var p=new Vector3(values[side+"T.x"],values[side+"T.y"],values[side+"T.z"]);p=Quaternion.Inverse(leveled)*original*p;var qr=Quaternion.Inverse(leveled)*original*rot(side+"Q",time);values[side+"T.x"]=p.x;values[side+"T.y"]=p.y;values[side+"T.z"]=p.z;values[side+"Q.x"]=qr.x;values[side+"Q.y"]=qr.y;values[side+"Q.z"]=qr.z;values[side+"Q.w"]=qr.w;}
            foreach(var key in values.Keys.ToArray())if((key.Contains("Spine")||key.Contains("Chest")||key.StartsWith("Head ")||key.StartsWith("Neck "))&&key.Contains("Left-Right"))values[key]-=means[key];foreach(var kv in values)keys[kv.Key].Add(new Keyframe(time,kv.Value));}
        var clip=UnityEngine.Object.Instantiate(source);clip.name="Crouch Walk Balanced";var curves=bindings.Select(b=>new AnimationCurve(keys[b.propertyName].ToArray())).ToArray();AnimationUtility.SetEditorCurves(clip,bindings,curves);clip.EnsureQuaternionContinuity();AssetDatabase.CreateAsset(clip,NewWalk);AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(Folder,"walk.txt"),"Removed mean body roll "+roll+" degrees; foot and hand goal trajectories preserved in body space; torso lateral and twist bias removed. Clip "+clip.length+"s human="+clip.humanMotion);
    }
    static void ApplyWalk(){if(Application.isPlaying)throw new Exception("Edit mode required");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var a=player.GetComponent<HumanoidAnimationDriver>().Animator;var c=a.runtimeAnimatorController as AnimatorController;var tree=c.layers[0].stateMachine.states.Single(s=>s.state.name=="Crouching").state.motion as BlendTree;var children=tree.children;if(AssetDatabase.GetAssetPath(children[1].motion)!="Assets/CharacterUpgrade/Animations/Player/Crouched Walking.fbx")throw new Exception("Current walk changed; inspect");var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(NewWalk);if(!clip||!clip.humanMotion)throw new Exception("Valid walk clip required");children[1].motion=clip;tree.children=children;EditorUtility.SetDirty(tree);EditorUtility.SetDirty(c);AssetDatabase.SaveAssets();File.WriteAllText(Path.Combine(Folder,"walk-applied.txt"),NewWalk);}
    static void Apply(){
        if(Application.isPlaying)throw new Exception("Apply in Edit mode");var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scenes/UTS.unity")throw new Exception("Expected current UTS");var player=UnityEngine.Object.FindAnyObjectByType<SimplePlayerController>();var a=player.GetComponent<HumanoidAnimationDriver>().Animator;var controller=a.runtimeAnimatorController as AnimatorController;var state=controller.layers[0].stateMachine.states.Single(s=>s.state.name=="Crouching").state;var tree=state.motion as BlendTree;if(!tree||!state.iKOnFeet||a.GetComponent<CrouchPoseAlignment>())throw new Exception("Crouch setup changed; inspect live state");var children=tree.children;if(children.Length!=2||AssetDatabase.GetAssetPath(children[0].motion)!="Assets/CharacterUpgrade/Animations/Player/Crouching Idle.fbx")throw new Exception("Current crouch motion changed; inspect rather than overwrite");var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(NewClip);if(!clip||!clip.humanMotion)throw new Exception("Balanced Humanoid clip missing");string backup="Assets/CharacterUpgrade/Backups/CrouchPose_"+DateTime.Now.ToString("yyyyMMdd_HHmmss");Directory.CreateDirectory(backup);AssetDatabase.Refresh();EditorSceneManager.SaveScene(scene,backup+"/UTS_BeforePosePolish.unity",true);AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(controller),backup+"/Player_BeforePosePolish.controller");children[0].motion=clip;tree.children=children;EditorUtility.SetDirty(tree);EditorUtility.SetDirty(controller);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);File.WriteAllText(Path.Combine(Folder,"applied.txt"),backup);
    }
}
